INSERT INTO `fpc_drama_script` VALUES (/*command_id*/19450027, /*drama_id*/945, /*command_type*/11, /*param_01*/'110411', /*param_02*/'用力过猛是什么意思啊。\n准备的材料不是很普通吗？\n嗯？　说起来，你买了\n樱粉色的鱼松吧。难道……', /*param_03*/'7', /*param_04*/'1', /*param_05*/'0', /*param_06*/'0', /*param_07*/'0', /*param_08*/'1');
